UPDATE articles SET seo_title = 'الوفاة في تركيا: إجراءات الدفن والوثائق المطلوبة', seo_description = 'عند الوفاة داخل تركيا: إثبات الوفاة، استخراج الوثائق اللازمة، ثم الدفن عبر مديرية المقابر البلدية. وللأجانب خطوات إضافية مع القنصلية وترجمة الوثائق.' WHERE slug = 'family-death-procedures';
