UPDATE articles SET seo_title = 'المهن الممنوعة والمسموحة للأجانب في تركيا 2026 بالقوانين', seo_description = 'المهن المحصورة بالمواطنين الأتراك (29 بنداً) مع رقم القانون لكل مهنة: طب الأسنان 1219، الصيدلة 6197، المحاماة 1136 — ولماذا لا يغيّرها إعفاء السوريين.' WHERE slug = 'professions-foreigners-turkey-2026';
UPDATE articles SET seo_title = 'عقد الإيجار في تركيا 2026: سقف الزيادة وحقوق المستأجر', seo_description = 'سقف زيادة الإيجار عند التجديد في تموز 2026 هو 32.03% وفق متوسط 12 شهراً (المادة 344)، بعد انتهاء سقف الـ25% — وحقوق المستأجر وأسباب الإخلاء المحصورة.' WHERE slug = 'rent-contract-tenant-rights-turkey-2026';
UPDATE articles SET seo_title = 'رفض الإقامة في تركيا: الأسباب والاعتراض خلال 60 يوماً', seo_description = 'أسباب رفض الإقامة الأكثر تكراراً وفق المادة 33 من قانون 6458، وقاعدة الأيام العشرة للمغادرة، وكيف ترفع دعوى أمام المحكمة الإدارية خلال 60 يوماً من التبليغ.' WHERE slug = 'residence-rejection-appeal-turkey-2026';
UPDATE articles SET seo_title = 'نصائح القبول في المنحة التركية: رسالة الدافع والمقابلة', seo_description = 'من 200 ألف متقدّم يُقبل 4-5 آلاف فقط: هيكل رسالة الدافع وطولها 3,000-5,000 حرف، التحضير للمقابلة، وأخطاء ترفض ملفك فوراً كالنسخ واستخدام الذكاء الاصطناعي.' WHERE slug = 'scholarship-application-tips';
UPDATE articles SET seo_title = 'المنح الدراسية في تركيا 2026: مقارنة كل الخيارات للعرب', seo_description = 'مقارنة منح تركيا 2026: Türkiye Bursları التي تغطي الرسوم والسكن والراتب، إعفاء سابانجي 100%، راتب بيلكنت 1,500$ شهرياً، TÜBITAK 2215، YTB-IsDB، وErasmus+.' WHERE slug = 'scholarship-turkey-overview';
UPDATE articles SET seo_title = 'منح الجامعات التركية: سابانجي وبيلكنت وكوتش وTÜBITAK', seo_description = 'بدائل منحة الحكومة التركية التي لا يتجاوز قبولها 4%: سابانجي بإعفاء يصل 100% وسكن، بيلكنت براتب شهري حتى 1,500 دولار، كوتش، TÜBITAK 2215، ومنحة YTB-IsDB.' WHERE slug = 'scholarship-university-programs';
