UPDATE articles SET seo_title = 'الدراسة في تركيا 2026: الجامعات والمنح والتكاليف', seo_description = 'المنحة التركية (راتب 3,500-7,000 ليرة وسكن وتأمين)، امتحان YÖS، رسوم الجامعات الحكومية والخاصة، معيشة 8,000-18,000 ليرة شهرياً، وإقامة الطالب' WHERE slug = 'study-in-turkey-universities-2026';
UPDATE articles SET seo_title = 'تجميد تسجيل السوريين في تركيا منذ 2022 والاستثناء الوحيد', seo_description = 'تركيا أوقفت تسجيل السوريين الجدد تحت الحماية المؤقتة منذ يونيو 2022 ولم تُلغِ القرار. الاستثناء الوحيد مواليد العائلات المسجّلة وفق المادة 21 وخطواته' WHERE slug = 'syria-registration-freeze-turkey';
