UPDATE articles SET seo_title = 'إعفاء السوريين من تصريح العمل: إعلان 26 حزيران 2026', seo_description = 'وزير الداخلية أعلن في 26 حزيران 2026 استبدال تصريح العمل بإعفاء (çalışma izni muafiyeti) للحماية المؤقتة. SGK يبقى إلزامياً، والنص التنفيذي لم يصدر' WHERE slug = 'syria-work-permit-exemption-turkey-2026-07';
