UPDATE articles SET seo_title = 'رسوم جواز السفر السوري 2026: 200 دولار عادي و400 مستعجل', seo_description = 'في القنصليات السورية: 200 دولار للدور العادي و400 للمستعجل، بشرط أن يكون الدولار إصدار 2017 أو أحدث. الأوراق المطلوبة وقواعد القاصرين والبصمة.' WHERE slug = 'syrian-passport-renewal';
UPDATE articles SET seo_title = 'أكواد التحديد (Tahdit) في تركيا: كيف تعرف وكيف تعترض', seo_description = 'كيف تتحقّق إن كان على ملفّك كود تحديد عبر إدارة الهجرة أو e-Devlet أو محامٍ، ولماذا لا تُنشر قائمة بمعاني الأكواد، وتصحيح خرافة مهلة الـ30 يوماً' WHERE slug = 'tahdit-entry-restriction-codes-how-to-object';
UPDATE articles SET seo_title = 'تعهّد الإخلاء في تركيا 2026: متى يُلزمك بالخروج ومتى يبطل', seo_description = 'المادة 352 من قانون الالتزامات 6098 تمنح المالك طريق إخلاء سريعاً خلال شهر: شروط صحّة تعهّد الإخلاء، متى يكون باطلاً، والفرق بينه وبين عقد الإيجار.' WHERE slug = 'tahliye-taahhutnamesi-eviction-undertaking-turkey-2026';
