UPDATE articles SET seo_title = 'حجز تذاكر القطار السريع YHT عبر تطبيق TCDD', seo_description = 'حجز YHT يتم عبر قنوات TCDD الرسمية، والتذاكر تنفد سريعاً في المواسم فاحجز مبكراً. وأدخل بياناتك بدقة حتى لا تُرفض التذكرة عند الصعود.' WHERE slug = 'travel-tcdd-yht-app';
