UPDATE articles SET seo_title = 'الإقامة طويلة الأمد في تركيا 2026: شرط 8 سنوات والمزايا', seo_description = 'إقامة غير محدّدة المدة لمن أمضى 8 سنوات متواصلة بإقامة نظامية (المادة 42 من القانون 6458)، وسنوات الطالب تُحسب بنصفها: المزايا واستثناء الحماية المؤقتة.' WHERE slug = 'uzun-donem-ikamet-turkey-8-yil-2026';
UPDATE articles SET seo_title = 'الرقم الضريبي في تركيا للأجانب: استخراجه أونلاين مجاناً', seo_description = 'الرقم الضريبي (Vergi Numarası) عشرة أرقام تصدرها GİB مجاناً وفوراً عبر dijital.gib.gov.tr أو من مكتب الضرائب، ولا يترتّب عليه التزام ضريبي تلقائي.' WHERE slug = 'vergi-numarasi-tax-number-foreigners';
UPDATE articles SET seo_title = 'مواعيد العودة الطوعية إلى سوريا: randevu.goc.gov.tr 2026', seo_description = 'حجز موعد العودة الطوعية إلكترونياً عبر randevu.goc.gov.tr في 81 ولاية: خطوات الحجز برقم الكملك، المعابر البرية والجوية المعتمدة، وعمل الحدود 24 ساعة.' WHERE slug = 'voluntary-return-syria-appointment-system-2026';
UPDATE articles SET seo_title = 'العودة الطوعية إلى سوريا 2026: هل يمكنك الرجوع لتركيا؟', seo_description = 'لا حظر دخول على من يعود طوعاً، لكن الحماية المؤقتة تنتهي وتُسحب بطاقتك والعودة تصبح تأشيرة تقديرية بلا ضمان — والخطوات والفرق بين الزيارة والانتقال' WHERE slug = 'voluntary-return-syria-procedure-2026';
UPDATE articles SET seo_title = 'إصابة العمل (İş Kazası) للأجانب في تركيا 2026: حقوقك', seo_description = 'ما يُعدّ إصابة عمل بالمادة 13 من قانون 5510، والتبليغ إلى SGK خلال 3 أيام عمل، والعلاج مجاناً وتعويض راحة بثلثي راتبك، وتعويض العجز والورثة.' WHERE slug = 'work-injury-is-kazasi-foreigners-2026';
UPDATE articles SET seo_title = 'الإعفاء من إذن العمل في تركيا 2026: من لا يحتاج إذناً', seo_description = 'الفئات المعفاة من إذن العمل حسب القانون 6735 ومدة كل إعفاء: محاضرون شهر، رياضيون 3 أشهر، طلاب Erasmus 4 أشهر، عمل زراعي موسمي 6 أشهر، والرسم 13,539 ليرة.' WHERE slug = 'work-permit-exemption-2026';
UPDATE articles SET seo_title = 'فيزا العمل للسوريين العائدين إلى تركيا: المعايير والأوراق', seo_description = 'لا يوجد راتب ثابت: القاعدة الرسمية مضاعفات الحدّ الأدنى بحسب المهنة (مهندس 4×، مدير 3×). الأوراق المطلوبة منك ومن الشركة، والتقديم من قنصلية خارج تركيا.' WHERE slug = 'work-visa-syrians-return-turkey-2026-06';
UPDATE articles SET seo_title = 'حقوق العامل في تركيا 2026: الساعات والإجازات والفصل', seo_description = 'قانون العمل 4857: 45 ساعة أسبوعياً وسقف 11 ساعة يومياً، أجر العمل الإضافي +50% والمدد الزائدة +25%، والإجازات والفصل — وحقوقك حتى بلا عقد مكتوب.' WHERE slug = 'worker-rights-turkey-2026';
UPDATE articles SET seo_title = 'تثبيت الطلاق الأجنبي في تركيا 2026: Tanıma-Tenfiz والنفوس', seo_description = 'طريقان لتصحيح قيدك من «متزوّج» إلى «مطلّق»: التسجيل الإداري في النفوس (المادة 27/A) أو دعوى الاعتراف أمام محكمة الأسرة. الفرق بينهما والأوراق والمزالق.' WHERE slug = 'yabanci-bosanma-tanima-tenfiz-turkiye-2026';
UPDATE articles SET seo_title = 'YKS أم YÖS 2026؟ المعيار مكان الثانوية لا الجنسية', seo_description = 'ما يحدّد امتحانك هو مكان إنهاء الثانوية: داخلها YKS وخارجها YÖS. تغيير 2026 أخرج خرّيجي الثانويات التركية من حصص الخارج، واستثناءات مدارس السفارات وMOBIS.' WHERE slug = 'yks-vs-yos-placement-by-schooling-2026';
UPDATE articles SET seo_title = 'التأمين الإجباري للسيارة 2026: السعر الأعلى ودرجات الضرر', seo_description = 'هيئة SEDDK تضع السعر الأعلى (Tavan) وهو يتغيّر شهرياً، ونظام درجات الضرر من 0 إلى 8 يقرّر ما تدفعه فعلاً مع لوحة ولايتك وسجل حوادثك. وكيف تخفّضه.' WHERE slug = 'zorunlu-trafik-sigortasi-tavan-basamak-2026';

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق
SELECT count(*) FILTER (WHERE length(seo_title) > 60)                       AS titles_still_too_long,
       count(*) FILTER (WHERE length(seo_description) > 160)                AS descs_still_too_long,
       count(*) FILTER (WHERE length(seo_description) BETWEEN 1 AND 69)     AS descs_still_too_short,
       count(*) FILTER (WHERE coalesce(seo_title,'') = '')                  AS titles_empty,
       count(*)                                                             AS total_published
FROM articles
WHERE status = 'approved' AND active IS NOT FALSE;
-- المتوقَّع بعد التشغيل: titles_still_too_long = 0، descs_still_too_long = 0.
-- ويبقى descs_still_too_short = 3 (المقالات الثلاثة المرفوضة عمداً)
-- و titles_empty = 32 (المقالات الكعوب — تحتاج محتوى أولاً، لا بيانات وصفية).
